#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int y, capacity, flow, cost;
    Edge() {}
    Edge(int y, int c, int f, int cost) : y(y), capacity(c), flow(f), cost(cost) {}
};

vector<Edge> edges_list;
const int MAXNODES = 14043;
vector<int> adj_list[MAXNODES];

long long total_cost_value = 0;
long long dist_arr[MAXNODES];
int parent_node_arr[MAXNODES], parent_edge_arr[MAXNODES], inq_arr[MAXNODES];

const long long INF_VAL = 1e18;
int s_node = MAXNODES - 2;
int t_node = MAXNODES - 1;

int residual_capacity(int idx) {
    return edges_list[idx].capacity - edges_list[idx].flow;
}

void find_path_and_push_flow() {
    for (int i = 0; i < MAXNODES; i++) {
        dist_arr[i] = INF_VAL;
        parent_node_arr[i] = -1;
        parent_edge_arr[i] = -1;
        inq_arr[i] = 0;
    }
    dist_arr[s_node] = 0;
    queue<int> q;
    q.push(s_node);
    inq_arr[s_node] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq_arr[u] = 0;
        for (auto e_idx : adj_list[u]) {
            if (residual_capacity(e_idx) == 0) continue;
            int y = edges_list[e_idx].y;
            int cst = edges_list[e_idx].cost;
            if (dist_arr[y] > dist_arr[u] + cst) {
                dist_arr[y] = dist_arr[u] + cst;
                parent_node_arr[y] = u;
                parent_edge_arr[y] = e_idx;
                if (!inq_arr[y]) {
                    inq_arr[y] = 1;
                    q.push(y);
                }
            }
        }
    }
    int cur = t_node;
    while (cur != s_node) {
        edges_list[parent_edge_arr[cur]].flow++;
        edges_list[parent_edge_arr[cur] ^ 1].flow--;
        cur = parent_node_arr[cur];
    }
    total_cost_value += dist_arr[t_node];
}

void create_edge(int from, int to, int cap, int cst) {
    adj_list[from].push_back(edges_list.size());
    edges_list.emplace_back(to, cap, 0, cst);
    adj_list[to].push_back(edges_list.size());
    edges_list.emplace_back(from, 0, 0, -cst);
}

int main() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) {
        int x; cin >> x; --x;
        create_edge(s_node, x, 1, 0);
    }
    int T = 101;
    for (int i = 0; i < T; i++)
        create_edge(i * n, t_node, k, i * c);
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y; --x; --y;
        for (int i = 0; i < T - 1; i++) {
            for (int j = 0; j < k; j++) {
                create_edge(x + i * n, y + i * n + n, 1, d * (j * 2 + 1));
            }
        }
        for (int i = 0; i < T - 1; i++) {
            for (int j = 0; j < k; j++) {
                create_edge(y + i * n, x + i * n + n, 1, d * (j * 2 + 1));
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < T - 1; j++) {
            create_edge(i + j * n, i + j * n + n, k, 0);
        }
    }
    for (int i = 0; i < k; i++) {
        find_path_and_push_flow();
    }
    cout << total_cost_value << endl;
}
